# Function to calculate each student's average grade
def calculate_student_averages(grades_data):
    """
    Calculates the average grade for each student.

    Parameters:
    - grades_data (dict): A dictionary where keys are student names and values are dictionaries mapping subjects to grades.

    Returns:
    dict: A dictionary mapping each student to their average grade.
    """
    averages = {}
    for student, grades in grades_data.items():
        averages[student] = sum(grades.values()) / len(grades)
    return averages

# Function to find the student with the highest average grade
def find_top_student(averages):
    """
    Identifies the student with the highest average grade.

    Parameters:
    - averages (dict): A dictionary mapping each student to their average grade.

    Returns:
    str: The name of the student with the highest average grade.
    """
    top_student = max(averages, key=averages.get)
    return top_student

# Function to find the subject with the highest average grade
def find_top_subject(grades_data):
    """
    Identifies the subject with the highest average grade across all students.

    Parameters:
    - grades_data (dict): A dictionary where keys are student names and values are dictionaries mapping subjects to grades.

    Returns:
    str: The name of the subject with the highest average grade.
    """
    subject_totals = {}
    subject_counts = {}
    for student, grades in grades_data.items():
        for subject, grade in grades.items():
            if subject not in subject_totals:
                subject_totals[subject] = grade
                subject_counts[subject] = 1
            else:
                subject_totals[subject] += grade
                subject_counts[subject] += 1

    avg_grades_by_subject = {subject: total / count for subject, total, count in zip(subject_totals.keys(), subject_totals.values(), subject_counts.values())}
    top_subject = max(avg_grades_by_subject, key=avg_grades_by_subject.get)

