from collections import defaultdict

def calculate_feature_engagement(engagement_data):
    # Initialize dictionaries to store the total users and count of days per feature
    total_users = defaultdict(int)
    num_days = defaultdict(int)

    # Dictionary to store the maximum engagement day per feature
    max_engagement_day = {}

    for feature, days in engagement_data.items():
        for day, users in days.items():
            total_users[feature] += users
            num_days[feature] += 1
            if feature not in max_engagement_day or users > max_engagement_day[feature][1]:
                max_engagement_day[feature] = (day, users)

    engagement = {}
    for feature in engagement_data:
        avg_dau = total_users[feature] / num_days[feature]
        engagement[feature] = {
            'average_dau': avg_dau,
            'max_engagement_day': max_engagement_day[feature][0],
            'max_engagement_users': max_engagement_day[feature][1]
        }

    return engagement
