```python
def analyze_population(zones_data):
    """
    Analyze the population dynamics across different ocean zones.

    Args:
    zones_data (dict): A dictionary containing data for different zones,
                       where each zone contains a list of dictionaries for each species,
                       with keys 'Species', 'Initial Population', 'Final Population'.

    Returns:
    dict: A dictionary summarizing the population status for each species in each zone.
    """
    population_status = {}
    for zone, species_list in zones_data.items():
        zone_summary = {}
        for species_data in species_list:
            species = species_data['Species']
            initial_population = species_data['Initial Population']
            final_population = species_data['Final Population']

            growth_rate = (final_population - initial_population) / initial_population

            if growth_rate > 0.1:
                status = "Thriving"
            elif -0.1 <= growth_rate <= 0.1:
                status = "Stable"
            else:
                status = "Endangered"

            zone_summary[species] = {'Growth Rate': growth_rate, 'Status': status}

        population_status[zone] = zone_summary

    return population_status

